import { health } from '../api/client.js';
import { mark } from './StatusMark.js';

// Reports what the API actually says, not what we hope. Any JSON reply from
// /api/health counts as connected; no reply, or a non-JSON reply, does not.
const TIMEOUT = 5000;
const EVERY = 30000;
const COPY = { checking: 'Checking…', up: 'Connected', down: 'Disconnected' };
const TONE = { checking: 'pending', up: 'ok', down: 'warn' };

async function probe() {
  try {
    await Promise.race([
      health(),
      new Promise((_, reject) => setTimeout(reject, TIMEOUT)),
    ]);
    return 'up';
  } catch {
    return 'down';
  }
}

export function mountBadge(el) {
  el.innerHTML = `<span class="badge-mark"></span>
    <span class="badge-label" aria-live="polite"></span>
    <time class="badge-time mono"></time>`;
  const [slot, label, time] = el.children;

  const paint = (state) => {
    if (el.dataset.state === state) return; // only announce real changes
    el.dataset.state = state;
    slot.innerHTML = mark(TONE[state]);
    label.textContent = COPY[state];
  };

  const check = async () => {
    paint(await probe());
    const now = new Date();
    time.dateTime = now.toISOString();
    time.textContent = now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  el.title = 'API health check, every 30 seconds';
  paint('checking');
  check();
  setInterval(check, EVERY);
}

