import { mountBadge } from './components/StatusBadge.js';
import { mark } from './components/StatusMark.js';

// Sample rows. Nothing behind them: the runs API isn't wired yet.
const RUNS = [
  { id: 'r-1041', service: 'checkout', status: 'passed', started: '09:12', duration: '2m 41s' },
  { id: 'r-1040', service: 'billing',  status: 'failed', started: '08:58', duration: '1m 07s' },
  { id: 'r-1039', service: 'catalog',  status: 'passed', started: '08:31', duration: '3m 22s' },
  { id: 'r-1038', service: 'notify',   status: 'passed', started: '08:04', duration: '0m 51s' },
];

const STATUS = {
  passed: { tone: 'ok', label: 'Passed' },
  failed: { tone: 'fail', label: 'Failed' },
};

// Design review only: ?state=loading|empty|error forces the other table states.
const VIEW = new URLSearchParams(location.search).get('state') ?? 'ready';

const NOT_WIRED = "isn't wired to the runs API in this build.";

function row(r) {
  const s = STATUS[r.status];
  return `<tr class="is-${r.status}">
    <td class="c-status"><span class="status">${mark(s.tone, { confirmed: false })}${s.label}</span></td>
    <th scope="row" class="mono">${r.id}</th>
    <td>${r.service}</td>
    <td class="mono num">${r.started}</td>
    <td class="mono num">${r.duration}</td>
    <td class="c-act"><button type="button" class="btn btn-quiet retry" data-run="${r.id}"
      aria-disabled="true" aria-describedby="wiring">Retry<span class="sr-only"> ${r.id}</span></button></td>
  </tr>`;
}

function skeleton() {
  return Array.from({ length: 4 }, () => `<tr class="skel">${
    '<td><span class="bar"></span></td>'.repeat(6)}</tr>`).join('');
}

function stateRow(tone, title, body, action = '') {
  return `<tr class="state"><td colspan="6">
    <div class="state-box">${mark(tone)}<div><p class="state-title">${title}</p>
    <p class="state-body">${body}</p>${action}</div></div>
  </td></tr>`;
}

function tbody() {
  if (VIEW === 'loading') return skeleton();
  if (VIEW === 'empty') {
    return stateRow('pending', 'No runs yet', 'Runs appear here as soon as a deploy starts.');
  }
  if (VIEW === 'error') {
    return stateRow('fail', "Couldn't load runs",
      "The runs API didn't answer. Nothing was changed.",
      '<button type="button" class="btn btn-quiet" id="reload">Try again</button>');
  }
  return RUNS.map(row).join('');
}

function summary() {
  if (VIEW !== 'ready') return '';
  const failed = RUNS.filter((r) => r.status === 'failed').length;
  const passed = RUNS.length - failed;
  return `<p class="summary">
    <span class="status is-failed">${mark('fail', { confirmed: false })}${failed} failed</span>
    <span class="status is-passed">${mark('ok', { confirmed: false })}${passed} passed</span>
    <span class="muted">Sample, not live</span>
  </p>`;
}

export function render() {
  document.querySelector('#app').innerHTML = `
    <header class="bar">
      <div class="brand">
        <span class="wordmark" aria-hidden="true">pulse</span>
        <h1>Deploy runs</h1>
      </div>
      <div class="bar-end">
        <div id="badge" class="badge"></div>
        <button type="button" id="new-run" class="btn btn-primary"
          aria-disabled="true" aria-describedby="wiring">New run</button>
      </div>
    </header>

    <main>
      <p id="wiring" class="notice">${mark('warn', { confirmed: false })}
        <span><strong>Sample data.</strong> These runs are placeholders. Retry and
        New run aren't wired to the runs API yet, so they won't start anything.</span>
      </p>

      <section aria-labelledby="runs-h">
        <div class="section-head">
          <h2 id="runs-h">Recent runs</h2>
          ${summary()}
        </div>
        <p id="feedback" class="feedback" role="status"></p>
        <div class="table-wrap" tabindex="0" role="region" aria-labelledby="runs-h">
          <table aria-busy="${VIEW === 'loading'}">
            <thead><tr>
              <th scope="col" class="c-status">Status</th>
              <th scope="col">Run</th>
              <th scope="col">Service</th>
              <th scope="col" class="num">Started</th>
              <th scope="col" class="num">Duration</th>
              <th scope="col" class="c-act"><span class="sr-only">Actions</span></th>
            </tr></thead>
            <tbody>${tbody()}</tbody>
          </table>
        </div>
      </section>
    </main>`;

  mountBadge(document.querySelector('#badge'));

  // Neither action has a backend yet. Say so instead of pretending.
  const feedback = document.querySelector('#feedback');
  document.querySelectorAll('.retry').forEach((b) => {
    b.addEventListener('click', () => {
      feedback.textContent = `Retry for ${b.dataset.run} wasn't sent. Retry ${NOT_WIRED}`;
    });
  });
  document.querySelector('#new-run').addEventListener('click', () => {
    feedback.textContent = `No run started. New run ${NOT_WIRED}`;
  });
  document.querySelector('#reload')?.addEventListener('click', () => location.reload());
}

render();

