.mark-open, .mark-pending { fill: none; }
.mark-ok { color: var(--ok); }
.mark-fail { color: var(--fail); }
.mark-warn { color: var(--warn); }
.mark-pending { color: var(--muted); }

.status { display: inline-flex; align-items: center; gap: 0.5rem; white-space: nowrap; }
.is-failed .status, .status.is-failed { color: var(--fail); font-weight: 600; }

/* ---- header ---- */
.bar {
  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between;
  gap: 0.75rem 1.5rem;
  padding: 0.875rem clamp(1rem, 3vw, 2rem);
  border-bottom: 1px solid var(--line);
}
.brand { display: flex; align-items: baseline; gap: 0.75rem; min-width: 0; }
.wordmark { font: 600 0.8125rem/1 var(--mono); color: var(--muted); }
h1 { font-size: 1.25rem; font-weight: 600; letter-spacing: -0.01em; }
.bar-end { display: flex; flex-wrap: wrap; align-items: center; gap: 0.75rem; }

.badge {
  display: inline-flex; align-items: center; gap: 0.5rem;
  min-height: 2.25rem; padding: 0 0.75rem;
  border: 1px solid var(--line); border-radius: 999px;
  white-space: nowrap;
}
.badge-mark { display: inline-flex; }
.badge-time { color: var(--muted); font-size: 0.75rem; }
.badge-time:empty { display: none; }
.badge[data-state="checking"] .mark { animation: breathe 1.4s var(--ease) infinite alternate; }
@keyframes breathe { to { opacity: 0.35; } }

/* ---- buttons ---- */
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  min-height: 2.25rem; padding: 0 0.875rem;
  font: 500 0.875rem/1 var(--sans); color: var(--ink);
  background: transparent; border: 1px solid var(--control); border-radius: var(--radius);
  cursor: pointer; white-space: nowrap;
  transition: background-color 150ms var(--ease), border-color 150ms var(--ease);
}
.btn:hover { background: var(--hover); }
.btn:active { background: var(--line); }
.btn-primary { background: var(--accent); border-color: var(--accent); color: var(--on-accent); font-weight: 600; }
.btn-primary:hover { background: oklch(0.8 0.11 250); }
.btn-quiet { min-height: 2rem; padding: 0 0.75rem; }
/* Not wired: outlined, like every other unconfirmed thing in the grammar. Still focusable. */
.btn[aria-disabled="true"] {
  background: transparent; color: var(--muted);
  border: 1px dashed var(--control); cursor: help;
}
.btn[aria-disabled="true"]:hover { background: var(--hover); }

/* ---- main ---- */
main {
  max-width: 72rem; margin: 0 auto;
  padding: 1.25rem clamp(1rem, 3vw, 2rem) 3rem;
  display: grid; gap: 1.5rem;
}

.notice {
  display: flex; gap: 0.625rem; align-items: baseline;
  padding: 0.75rem 1rem;
  background: var(--notice); border: 1px solid oklch(0.36 0.05 80); border-radius: var(--radius);
  max-width: 75ch;
}
.notice .mark { position: relative; top: 1px; }
.notice strong { color: var(--warn); font-weight: 600; }

.section-head {
  display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between;
  gap: 0.5rem 1.5rem; margin-bottom: 0.5rem;
}
h2 { font-size: 1rem; font-weight: 600; }
.summary { display: flex; flex-wrap: wrap; gap: 0.5rem 1.25rem; align-items: center; }
.summary .muted { font-size: 0.75rem; }

.feedback { min-height: 1.55em; margin-bottom: 0.5rem; color: var(--muted); }

/* ---- table ---- */
.table-wrap {
  overflow-x: auto;
  background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius);
}
table { width: 100%; min-width: 34rem; border-collapse: collapse; table-layout: fixed; }
th, td {
  padding: 0 1rem; height: 2.75rem;
  text-align: start; vertical-align: middle;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
thead th {
  height: 2.25rem; font-size: 0.75rem; font-weight: 500; color: var(--muted);
  border-bottom: 1px solid var(--line);
}
thead .num { text-align: end; }
tbody th { font-weight: 500; }
tbody tr + tr > * { border-top: 1px solid var(--line); }
tbody tr:not(.state, .skel):hover { background: var(--hover); }

.c-status { width: 8rem; }
.c-act { width: 6.5rem; text-align: end; }
th:nth-child(2) { width: 7rem; }
th:nth-child(4), th:nth-child(5) { width: 6.5rem; }

/* skeleton: same row height as real rows, so nothing jumps */
.skel .bar {
  display: block; height: 0.625rem; width: 70%; border-radius: 3px;
  background: var(--hover); animation: breathe 1.2s var(--ease) infinite alternate;
}

.state td { height: auto; white-space: normal; padding: 2.5rem 1rem; }
.state-box { display: flex; gap: 0.75rem; align-items: baseline; max-width: 40ch; margin: 0 auto; }
.state-box .mark { position: relative; top: 1px; }
.state-title { font-weight: 600; }
.state-body { color: var(--muted); margin-bottom: 0.75rem; }
.state-body:last-child { margin-bottom: 0; }

@media (pointer: coarse) {
  .btn, .btn-quiet, .badge { min-height: 2.75rem; }
  th, td { height: 3.25rem; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation: none !important; transition: none !important; }
}
